package com.kidsvideo.app;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.os.Bundle;import android.speech.RecognitionListener;import android.speech.RecognizerIntent;import android.speech.SpeechRecognizer;import android.content.Intent;import java.util.ArrayList;
public final class SpeechHelper {
 public interface Callback{void onResult(String text);void onError(String message);} public static final int AUDIO_PERMISSION_REQUEST=701; private final Activity activity; private SpeechRecognizer recognizer; private Callback pending; public SpeechHelper(Activity a){activity=a;}
 public void listen(String locale,Callback callback){pending=callback;if(activity.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){activity.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},AUDIO_PERMISSION_REQUEST);if(callback!=null)callback.onError("Microphone permission is required. Tap the microphone again after allowing it.");return;}if(!SpeechRecognizer.isRecognitionAvailable(activity)){if(callback!=null)callback.onError("Speech recognition is not available on this device.");return;}destroyRecognizer();recognizer=SpeechRecognizer.createSpeechRecognizer(activity);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle p){}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){}public void onBufferReceived(byte[]b){}public void onEndOfSpeech(){}public void onError(int e){if(pending!=null)pending.onError(errorMessage(e));}public void onResults(Bundle results){ArrayList<String>v=results.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(v!=null&&!v.isEmpty()){if(pending!=null)pending.onResult(v.get(0));}else if(pending!=null)pending.onError("I didn't catch that. Please try again.");}public void onPartialResults(Bundle p){}public void onEvent(int t,Bundle p){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,locale);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_PREFERENCE,locale);i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Speak in English");i.putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,3);recognizer.startListening(i);}
 private static String errorMessage(int e){switch(e){case SpeechRecognizer.ERROR_AUDIO:return "There was an audio problem.";case SpeechRecognizer.ERROR_CLIENT:return "Speech recognition stopped. Please try again.";case SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS:return "Microphone permission is required.";case SpeechRecognizer.ERROR_NETWORK:return "Speech recognition needs a network connection right now.";case SpeechRecognizer.ERROR_NETWORK_TIMEOUT:return "Speech recognition timed out.";case SpeechRecognizer.ERROR_NO_MATCH:return "I didn't catch that. Please try again.";case SpeechRecognizer.ERROR_RECOGNIZER_BUSY:return "The microphone is busy. Please try again.";case SpeechRecognizer.ERROR_SERVER:return "The speech service is temporarily unavailable.";case SpeechRecognizer.ERROR_SPEECH_TIMEOUT:return "I didn't hear anything. Please try again.";default:return "Speech recognition couldn't understand that. Please try again.";}}
 public void destroy(){destroyRecognizer();} private void destroyRecognizer(){if(recognizer!=null){try{recognizer.cancel();}catch(Exception ignored){}try{recognizer.destroy();}catch(Exception ignored){}recognizer=null;}}
}
